funkin_options_Options.load = function() {
	if(funkin_options_Options.__save == null) {
		funkin_options_Options.__save = new flixel_util_FlxSave();
	}
	funkin_options_Options.__save.bind("options","CodenameEngine");
	funkin_options_Options.__load();
	if(!funkin_options_Options.__eventAdded) {
		openfl_Lib.get_application().onExit.add(function(i) {
			funkin_backend_system_Logs.__showInConsole(funkin_backend_system_Logs.prepareColoredTrace([funkin_backend_system_Logs.logText("[" + "Options" + "] ",9),funkin_backend_system_Logs.logText("Saving "),funkin_backend_system_Logs.logText("settings",10),funkin_backend_system_Logs.logText("...")],4));
			funkin_options_Options.save();
		});
		funkin_options_Options.__eventAdded = true;
	}
	flixel_FlxG.sound.set_volume(funkin_options_Options.volume);
	funkin_options_Options.applySettings();
};
funkin_options_Options.applySettings = function() {
	funkin_options_Options.applyKeybinds();
	switch(funkin_options_Options.quality) {
	case 0:
		funkin_options_Options.antialiasing = false;
		funkin_options_Options.lowMemoryMode = true;
		funkin_options_Options.gameplayShaders = false;
		break;
	case 1:
		funkin_options_Options.antialiasing = true;
		funkin_options_Options.lowMemoryMode = false;
		funkin_options_Options.gameplayShaders = true;
		break;
	}
	flixel_FlxG.sound.defaultMusicGroup.set_volume(funkin_options_Options.volumeMusic);
	flixel_FlxG.game.stage.set_quality((flixel_FlxG.enableAntialiasing = funkin_options_Options.antialiasing) ? 0 : 2);
	flixel_FlxG.autoPause = funkin_options_Options.autoPause;
	if(flixel_FlxG.updateFramerate < funkin_options_Options.framerate) {
		flixel_FlxG.set_drawFramerate(flixel_FlxG.set_updateFramerate(funkin_options_Options.framerate));
	} else {
		flixel_FlxG.set_updateFramerate(flixel_FlxG.set_drawFramerate(funkin_options_Options.framerate));
	}
};
